      const {pipeline,env}=await import('@huggingface/transformers');
      env.allowLocalModels=false;env.useBrowserCache=true;
      if(!sttPipelineRef.current)sttPipelineRef.current=pipeline('automatic-speech-recognition','onnx-community/whisper-small',{dtype:'q8'});
      const transcriber=await sttPipelineRef.current;
