        if((token.startsWith('**')&&token.endsWith('**'))||(token.startsWith('__')&&token.endsWith('__'))) nodes.push(<strong key={index++}>{token.slice(2,-2)}</strong>);
        else if(token.startsWith('*')&&token.endsWith('*')) nodes.push(<em key={index++}>{token.slice(1,-1)}</em>);
        else if(token.startsWith('_')&&token.endsWith('_')) nodes.push(<em key={index++}>{token.slice(1,-1)}</em>);
